import type { ChunkSourceMetadata } from './chunk';
import type { SourceStats } from './ops';
import type { FileInfo, InputFormat } from './read';
/**
 * Shared rendering for the `info` and `stats` actions. Both actions report the
 * same structural block (the info fields); `stats` appends per-LOD, per-column
 * statistics — so the stats output is a strict superset of the info output in
 * both text and JSON form.
 */
type OutputFormat = 'text' | 'json';
type InfoMeta = Pick<ChunkSourceMetadata, 'numGaussians' | 'numLods' | 'lodCounts' | 'shBands' | 'model' | 'availableLayers' | 'extraColumns'>;
/**
 * Render a source's structural metadata for the `info` action — the detected
 * input format (when known), the gaussian verdict ({@link hasGaussianLayers}:
 * `false` for e.g. a plain point-cloud PLY), per-LOD counts, SH bands, available
 * layers, and the extra (non-standard `other`-layer) columns, all from `meta`
 * (no data read).
 * @param meta - The source metadata.
 * @param format - Output format. Default: 'text'
 * @param sourceFormat - Detected input format; reported when provided.
 * @returns A text or JSON block for `logger.output`.
 */
declare const formatSourceInfo: (meta: InfoMeta, format?: OutputFormat, sourceFormat?: InputFormat) => string;
/**
 * Render a {@link FileInfo} exactly as the `info` action renders the same file's
 * source, for reporting from {@link readFileInfo} without opening the source.
 * @param info - The file info.
 * @param format - Output format. Default: 'text'
 * @returns A text or JSON block for `logger.output`.
 */
declare const formatFileInfo: (info: FileInfo, format?: OutputFormat) => string;
/**
 * Render a source's statistics for the `stats` action: the info block followed
 * by one table per LOD (text), or the info object plus a per-LOD columnar
 * `stats` array (JSON — the {@link LodStats} shape, with `displayMean` and
 * `displayStdDev` reported as `mean` and `stdDev`). Values are shown in display space (see
 * {@link forwardTransforms}); histogram bin edges span `[min[i], max[i]]`.
 * @param meta - The source metadata.
 * @param stats - The computed per-LOD statistics.
 * @param format - Output format. Default: 'text'
 * @param sourceFormat - Detected input format; reported when provided.
 * @returns A text or JSON block for `logger.output`.
 */
declare const formatSourceStats: (meta: ChunkSourceMetadata, stats: SourceStats, format?: OutputFormat, sourceFormat?: InputFormat) => string;
export { formatFileInfo, formatSourceInfo, formatSourceStats };
